\label{lem:MLSI-equivalence}
Let $\omega$ be a faithful invariant state of $\Phi_t=e^{t\mathcal L}$ and let $\alpha>0$.  The estimate $D(\Phi_t(\rho)\|\omega)\le e^{-\alpha t}D(\rho\|\omega)$ for all states and all $t\ge0$ is equivalent to
\begin{equation*}
 \alpha D(\rho\|\omega)\le\operatorname{EP}_{\mathcal L}(\rho),
 \qquad \rho\in D(\mathcal L)\cap B(\omega).
\end{equation*}

\label{thm:Gross}
Under the semigroup assumptions of \cref{thm:main}, the endpoint \eqref{eq:24-main} implies, for every standard-form vector $X\in D(\mathcal E)\subset\mathscr T_2(\mathcal H)$,
\begin{equation}\label{eq:defective-general}
 \operatorname{Ent}_{2,\sigma}(X)
 \le4s\mathcal E(X)+4\log C\|X\|_2^2.
\end{equation}
Consequently, for every state $\rho$ with $\sqrt\rho\in D(\mathcal E)$,
\begin{equation}\label{eq:Rothaus}
 D(\rho\|\sigma)\le4s\mathcal E(\sqrt\rho)
 +(4\log C+2)\|\sqrt\rho-\langle\sqrt\sigma,\sqrt\rho\rangle\sqrt\sigma\|_2^2.
\end{equation}
If the gap is $\lambda>0$, then
\begin{equation}\label{eq:tight-LSI}
 D(\rho\|\sigma)
 \le c_{\rm LS}\mathcal E(\sqrt\rho),
 \qquad c_{\rm LS}=4s+\frac{4\log C+2}{\lambda}.
\end{equation}
For $C=1$, \eqref{eq:defective-general} directly gives \eqref{eq:tight-LSI} with $c_{\rm LS}=4s$ and no gap assumption.

\label{lem:rothaus-entropy-domain}
Let $\sigma$ be a faithful density matrix on $\mathcal H$.  For every
$Y\in\mathscr T_2(\mathcal H)$ and $a\in\mathbb C$,
\begin{equation}\label{eq:rothaus-entropy-domain}
 \operatorname{Ent}_{2,\sigma}(Y+a\sqrt\sigma)
 \le\operatorname{Ent}_{2,\sigma}(Y)+2\|Y\|_2^2.
\end{equation}
Infinite values are allowed.  In particular, the estimate applies to
the centred vector $Y=X-\langle\sqrt\sigma,X\rangle\sqrt\sigma$
whenever its entropy is finite.

\label{lem:entropy-approximation}
For every state $\rho$ there are $\rho_k\in B(\sigma)$ such that
\begin{equation}\label{eq:entropy-approximation}
 \|\rho_k-\rho\|_1\longrightarrow0,
 \qquad D(\rho_k\|\sigma)\longrightarrow D(\rho\|\sigma)
\end{equation}
in the extended nonnegative reals.

\label{lem:weighted-SDPI}
Let $\Phi$ be a normal channel with faithful invariant state $\sigma$,
let $T=\Phi^*$, and assume that $T$ is $\sigma$-KMS symmetric and extends
consistently to positive contractions on $L^r(\sigma)$ for
$1\le r\le\infty$. Suppose that, for some $1\le K<\infty$,
\begin{equation}\label{eq:pq-SDPI-input}
 \|T:L^p(\sigma)\to L^q(\sigma)\|\le K,
 \qquad 1<p\le q<\infty.
\end{equation}
Then
\begin{equation}\label{eq:weighted-SDPI}
 D(\Phi(\rho)\|\sigma)
 \le \frac{(p-1)q}{p(q-1)}D(\rho\|\sigma)
 +\frac q{q-1}\log K
\end{equation}
for every state $\rho$.

\label{lem:paired-generator}
Let $\rho$ be a faithful state,
$K_\rho=\log\rho-\log\sigma_\beta$, and write
$a_\nu=\beta\nu/2$.  Define
\begin{align*}
 U_{\alpha,\nu}
 &:=e^{-a_\nu/2}A_\nu^\alpha\sqrt\rho
     -e^{a_\nu/2}\sqrt\rho A_\nu^\alpha,\\
 W_{\alpha,\nu}
 &:=e^{-a_\nu}A_\nu^\alpha\rho
     -e^{a_\nu}\rho A_\nu^\alpha,
 \qquad
 V_{\alpha,\nu}:=[A_\nu^\alpha,K_\rho].
\end{align*}
Let $\mathcal E_{\sigma_E}$ be the standard-form Dirichlet form associated
with $\mathcal L_{\sigma_E}$.  Its energy and the entropy production
satisfy
\begin{align}
 \mathcal E_{\sigma_E}(\sqrt\rho)
 &=\operatorname{Re}\sum_{\alpha,\nu,\mu}
 c_{\nu\mu}^{(\sigma_E)}
 \operatorname{Tr}(U_{\alpha,\nu}^\dagger U_{\alpha,\mu}),
 \label{eq:E-paired-generator}\\
 \operatorname{EP}_{\mathcal L_{\sigma_E}}(\rho)
 &=\operatorname{Re}\sum_{\alpha,\nu,\mu}
 c_{\nu\mu}^{(\sigma_E)}
 \operatorname{Tr}(W_{\alpha,\nu}^\dagger V_{\alpha,\mu}).
 \label{eq:EP-paired-generator}
\end{align}

Put $Y=\sqrt\rho$.  The four terms in the first pairing are
\begin{align*}
 \operatorname{Tr}(U_{\alpha,\nu}^\dagger U_{\alpha,\mu})
 ={}&e^{-(a_\nu+a_\mu)/2}\operatorname{Tr}(Y(A_\nu^\alpha)^\dagger A_\mu^\alpha Y)\\
 &-e^{(a_\mu-a_\nu)/2}\operatorname{Tr}(Y(A_\nu^\alpha)^\dagger Y A_\mu^\alpha)\\
 &-e^{(a_\nu-a_\mu)/2}\operatorname{Tr}((A_\nu^\alpha)^\dagger Y A_\mu^\alpha Y)\\
 &+e^{(a_\nu+a_\mu)/2}\operatorname{Tr}((A_\nu^\alpha)^\dagger Y^2 A_\mu^\alpha).
\end{align*}
Multiply by $c_{\nu\mu}^{(\sigma_E)}$ and sum.  Using
$\sigma_\beta^tA_\nu^\alpha\sigma_\beta^{-t}
=e^{-2ta_\nu}A_\nu^\alpha$ and pairing the adjoint rows turns this sum into
\[
 -\operatorname{Tr}\!\left(Y\sigma_\beta^{-1/4}
 \mathcal L_{\sigma_E}(\sigma_\beta^{1/4}Y\sigma_\beta^{1/4})
 \sigma_\beta^{-1/4}\right)
 =\mathcal E_{\sigma_E}(Y).
\]
This is the first formula.  For the second, the modular relation
$[\log\sigma_\beta,A_\nu^\alpha]=-2a_\nu A_\nu^\alpha$ gives
\[
 V_{\alpha,\nu}
 =A_\nu^\alpha\log(e^{-a_\nu}\rho)
  -\log(e^{a_\nu}\rho)A_\nu^\alpha.
\]
The KMS identity for the filter reads
$\widehat f(-\nu)=e^{a_\nu}\overline{\widehat f(\nu)}$, hence
\begin{equation}\label{eq:generator-c-involution}
 c_{-\mu,-\nu}^{(\sigma_E)}=c_{\nu\mu}^{(\sigma_E)}
 \quad\text{under}\quad
 (\alpha,\nu,\mu)\longmapsto(\bar\alpha,-\mu,-\nu).
\end{equation}
Expansion and cyclicity give the real part of
\begin{align*}
 \sum_{\alpha,\nu,\mu}c_{\nu\mu}^{(\sigma_E)}\big[{}
 &e^{-a_\nu}\operatorname{Tr}(\rho(A_\nu^\alpha)^\dagger A_\mu^\alpha K_\rho)
 -e^{-a_\nu}\operatorname{Tr}(A_\mu^\alpha\rho(A_\nu^\alpha)^\dagger K_\rho)\\
 &-e^{a_\nu}\operatorname{Tr}((A_\nu^\alpha)^\dagger\rho A_\mu^\alpha K_\rho)
 +e^{a_\nu}\operatorname{Tr}(A_\mu^\alpha(A_\nu^\alpha)^\dagger\rho K_\rho)\big].
\end{align*}
Reindexing the last two terms by \eqref{eq:generator-c-involution}, and writing
\[
 p_{\nu\mu}:=\frac{e^{d_{\nu\mu}}}{2\cosh d_{\nu\mu}},
\]
use
\begin{align*}
 c_{\nu\mu}^{(\sigma_E)}e^{-a_\nu}
 &=q_{\nu\mu}^{(\sigma_E)}(1-p_{\nu\mu}), \
 c_{\nu\mu}^{(\sigma_E)}e^{-a_\mu}
 =q_{\nu\mu}^{(\sigma_E)}p_{\nu\mu},\text{ and }
 c_{\nu\mu}^{(\sigma_E)}(e^{-a_\nu}+e^{-a_\mu})
 =q_{\nu\mu}^{(\sigma_E)}.
\end{align*}
to obtain
\begin{align*}
 \operatorname{Re}\sum_{\alpha,\nu,\mu}q_{\nu\mu}^{(\sigma_E)}
 \big[{}&-\operatorname{Tr}(A_\mu^\alpha\rho(A_\nu^\alpha)^\dagger K_\rho)
 +p_{\nu\mu}\operatorname{Tr}((A_\nu^\alpha)^\dagger A_\mu^\alpha\rho K_\rho)\\
 &+(1-p_{\nu\mu})\operatorname{Tr}(\rho(A_\nu^\alpha)^\dagger
 A_\mu^\alpha K_\rho)\big],
\end{align*}
This is $-\operatorname{Tr}(\mathcal L_{\sigma_E}(\rho)K_\rho)$ by
\eqref{eq:cross-frequency-generator}.

\label{thm:SV-exhaustion}
Suppose that an SV-admissible exhaustion exists on
$D(\mathcal L_0)\cap B(\sigma_\beta)$. Then the Stroock--Varopoulos hypothesis \eqref{eq:SV-assumption} of \cref{thm:main} holds on this class. Consequently, \cref{thm:main} applies whenever its remaining hypotheses---the identification \eqref{eq:L2-link}, positive contractions on the weighted spaces, the bound \eqref{eq:24-main}, and a positive gap when $C>1$---are satisfied.

\label{cor:Davies-main}
For a primitive finite-dimensional Davies generator,
\cref{thm:SV-finite} proves the SV inequality. Hence \cref{thm:main}
applies if the weighted extensions are positive contractions, satisfy
\eqref{eq:L2-link}, and obey \eqref{eq:24-main}. The same conclusion
holds in infinite dimension under \cref{def:SV-exhaustion}.

\label{lem:single-complement}
For every $2\le p_*<\infty$, the operators $B_{d,\pm,p}$ and
$b_{d,+}(N)$ are bounded uniformly for $2\le p\le p_*$.  Hence
\begin{equation*}
 \mathscr V_{d,p}(X):=B_{d,+,p}XB_{d,+,p}^\dagger
 +B_{d,-,p}XB_{d,-,p}^\dagger
 -\frac12\{b_{d,+}(N),X\}
\end{equation*}
satisfies
\begin{equation}\label{eq:single-complement-bound}
 \sup_{2\le p\le p_*}\|\mathscr V_{d,p}\|_{p\to p}<\infty.
\end{equation}
